import{_ as r,o as t,c as o,ag as a}from"./chunks/framework.DMVuHR7L.js";const s="/web-logcat/staging/docs/assets/mirror-default.BvPVuWIW.png",g=JSON.parse('{"title":"Screen Mirror","description":"","frontmatter":{},"headers":[],"relativePath":"features/screen-mirror.md","filePath":"features/screen-mirror.md","lastUpdated":1778211676000}'),i={name:"features/screen-mirror.md"};function n(c,e,d,l,h,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="screen-mirror" tabindex="-1">Screen Mirror <a class="header-anchor" href="#screen-mirror" aria-label="Permalink to &quot;Screen Mirror&quot;">​</a></h1><p>The Screen Mirror widget is a scrcpy-style live screen of the device, decoded in the browser via <strong>WebCodecs</strong>. It&#39;s capped at one instance per dashboard so two Mirror tiles can&#39;t fight for the same H.264 stream.</p><p><img src="'+s+'" alt="Screen Mirror tile"></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>WebLogcat ships a copy of <code>scrcpy-server-v2.7.jar</code> and pushes it to the device on connect. The server captures the screen and streams an H.264 NAL stream back over the ADB transport; the widget decodes it using the <code>@yume-chan/scrcpy-decoder-webcodecs</code> decoder and renders the frames to a <code>&lt;canvas&gt;</code>.</p><p>Latency is roughly 50–150 ms over USB on a Pixel — not as tight as a native <code>scrcpy</code>, but indistinguishable for non-game use.</p><h2 id="interaction" tabindex="-1">Interaction <a class="header-anchor" href="#interaction" aria-label="Permalink to &quot;Interaction&quot;">​</a></h2><ul><li><strong>Tap, drag, swipe.</strong> Click on the canvas to send tap events. Drag to swipe. Multi-touch is mapped from <code>touch</code> events on touchscreens; on a laptop, click counts as a single touch.</li><li><strong>Hardware buttons.</strong> The bezel renders the standard Android buttons — Back, Home, Recents — plus power, volume up/down, rotate, screenshot, and record.</li><li><strong>Type into the device.</strong> Click the canvas first to focus, then type. Modifier keys forward through.</li></ul><h2 id="recording" tabindex="-1">Recording <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Recording&quot;">​</a></h2><p>The record button starts an MP4 capture of the live stream — encoded with <code>mp4-muxer</code> directly in the browser, no server round-trip. The recording icon turns red while it&#39;s running; click it again to stop. The MP4 is saved to your downloads folder.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The camera icon writes the current frame as a PNG to your downloads folder. Lossless, full device resolution.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Overlay font size.</strong> Affects the per-frame stats overlay (toggled via the eye icon).</li><li><strong>Bitrate cap.</strong> Trade quality vs. bandwidth. Defaults to 8 Mbps.</li><li><strong>Display rotation.</strong> Force portrait, landscape, or auto.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Mirror needs a Chromium build with <strong>WebCodecs</strong> (Chrome / Edge 94+). Older browsers fall back to a <em>not supported</em> notice.</li><li>The device needs to be modern enough to run the bundled scrcpy server (Android 7+ in practice).</li><li>Some manufacturers block screen capture from certain apps (banking, DRM-protected video). Those frames render black — that&#39;s the device, not WebLogcat.</li></ul>',16)])])}const m=r(i,[["render",n]]);export{g as __pageData,m as default};
